window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["GAL"]={"book":"GAL","editions":{"dan-1819":[[1,1,"Paulus, Apostel (ikke af Mennesker og ikke ved noget Menneske, men ved Jesus Christus og Gud Fader, som ham opreiste fra de Døde)","Paulus, Apostel (ikke af Mennesker og ikke ved noget Menneske, men ved Jesus Christus og Gud Fader, som ham opreiste fra de Døde)"],[1,2,"og alle Brødrene, som ere med mig, til Menighederne i Galatia:","og alle Brødrene, som ere med mig, til Menighederne i Galatia:"],[1,3,"Naade være med Eder og Fred, fra Gud Fader og vor Herre Jesus Christus,","Naade være med Eder og Fred, fra Gud Fader og vor Herre Jesus Christus,"],[1,4,"som hengav sig selv for vore Synder, paa det han kunde udfrie os fra den nærværende onde Verden, efter vor Guds og Faders Villie,","som hengav sig selv for vore Synder, paa det han kunde udfrie os fra den nærværende onde Verden, efter vor Guds og Faders Villie,"],[1,5,"hvilken være Ære i al Evighed! Amen.","hvilken være Ære i al Evighed! Amen."],[1,6,"Jeg undrer paa, at I saa snart lade Eder afvende fra den, som kaldte Eder ved Christi Naade, til et andet Evangelium;","Jeg undrer paa, at I saa snart lade Eder afvende fra den, som kaldte Eder ved Christi Naade, til et andet Evangelium;"],[1,7,"enddog der er intet andet, kun ere der Nogle, som forvilde Eder og ville forvende Christi Evangelium.","enddog der er intet andet, kun ere der Nogle, som forvilde Eder og ville forvende Christi Evangelium."],[1,8,"Men dersom endog vi eller en Engel af Himmelen prædiker Eder Evangelium anderledes, end vi have prædiket Eder det, han være en Forbandelse!","Men dersom endog vi eller en Engel af Himmelen prædiker Eder Evangelium anderledes, end vi have prædiket Eder det, han være en Forbandelse!"],[1,9,"Som jeg sagde, saa siger jeg nu igjen: dersom Nogen prædiker Eder Evangelium anderledes, end I have annammet det, han være en Forbandelse.","Som jeg sagde, saa siger jeg nu igjen: dersom Nogen prædiker Eder Evangelium anderledes, end I have annammet det, han være en Forbandelse."],[1,10,"Taler jeg vel nu Mennesker til Villie, eller Gud? eller søger jeg at tækkes Mennesker? Dersom jeg endnu tækkedes Mennesker, da var jeg ikke Christi Tjener.","Taler jeg vel nu Mennesker til Villie, eller Gud? eller søger jeg at tækkes Mennesker? Dersom jeg endnu tækkedes Mennesker, da var jeg ikke Christi Tjener."],[1,11,"Jeg bevidner Eder, Brødre! at det Evangelium, som er prædiket af mig, er ikke Menneske-Lære;","Jeg bevidner Eder, Brødre! at det Evangelium, som er prædiket af mig, er ikke Menneske-Lære;"],[1,12,"thi hverken annammede, ei heller lærte jeg det af noget Menneske men ved Jesu Christi Aabenbarelse.","thi hverken annammede, ei heller lærte jeg det af noget Menneske men ved Jesu Christi Aabenbarelse."],[1,13,"I have jo hørt om min Vandel forhen i Jødedommen, at jeg over al Maade forfulgte Guds Menighed og forstyrrede den.","I have jo hørt om min Vandel forhen i Jødedommen, at jeg over al Maade forfulgte Guds Menighed og forstyrrede den."],[1,14,"Og jeg gik langt videre i Jødedommen, end mange af mine Jævnaldrende i mit Folk, idet jeg var overmaade nidkjær for mine fædrene Lærdomme.","Og jeg gik langt videre i Jødedommen, end mange af mine Jævnaldrende i mit Folk, idet jeg var overmaade nidkjær for mine fædrene Lærdomme."],[1,15,"Men der det behagede Gud, som fra Moders Liv havde udseet mig, og som kaldte mig ved sin Naade,","Men der det behagede Gud, som fra Moders Liv havde udseet mig, og som kaldte mig ved sin Naade,"],[1,16,"at aabenbare sin Søn i mig, paa det jeg skulde forkynde ham iblandt Hedningerne: da strax bespurgte jeg mig ikke med Kjød og Blod,","at aabenbare sin Søn i mig, paa det jeg skulde forkynde ham iblandt Hedningerne: da strax bespurgte jeg mig ikke med Kjød og Blod,"],[1,17,"drog heller ikke op til Jerusalem, til dem, som før jeg vare Apostler, men drog bort til Arabien, og kom atter tilbage til Damascus.","drog heller ikke op til Jerusalem, til dem, som før jeg vare Apostler, men drog bort til Arabien, og kom atter tilbage til Damascus."],[1,18,"Siden, efter tre Aar, drog jeg op til Jerusalem, for at blive kjendt med Petrus, og blev femten Dage hos ham.","Siden, efter tre Aar, drog jeg op til Jerusalem, for at blive kjendt med Petrus, og blev femten Dage hos ham."],[1,19,"Men nogen anden af Apostlerne saae jeg ikke, uden Jakobus, Herrens Broder.","Men nogen anden af Apostlerne saae jeg ikke, uden Jakobus, Herrens Broder."],[1,20,"(Hvad jeg skriver Eder, see, det vidner jeg for Guds Aasyn, at jeg ikke lyver.)","(Hvad jeg skriver Eder, see, det vidner jeg for Guds Aasyn, at jeg ikke lyver.)"],[1,21,"Derefter kom jeg til Syriens og Ciliciens Lande.","Derefter kom jeg til Syriens og Ciliciens Lande."],[1,22,"Men af Person var jeg ubekjendt for Christi Menigheder i Judæa;","Men af Person var jeg ubekjendt for Christi Menigheder i Judæa;"],[1,23,"kun havde de hørt: den, som os tilforn forfulgte, prædiker nu den Tro, som han tilforn vilde udrydde;","kun havde de hørt: den, som os tilforn forfulgte, prædiker nu den Tro, som han tilforn vilde udrydde;"],[1,24,"og de prisede Gud for mig.","og de prisede Gud for mig."],[2,1,"Siden, efter fjorten Aar, drog jeg atter op til Jerusalem med Barnabas, og tog ogsaa Titus med.","Siden, efter fjorten Aar, drog jeg atter op til Jerusalem med Barnabas, og tog ogsaa Titus med."],[2,2,"Men jeg drog op efter en Aabenbarelse og forelagde dem, men de Ansete i Særdeleshed, det Evangelium, som jeg prædiker iblandt Hedningerne, om jeg vel løber eller haver løbet forgjeves.","Men jeg drog op efter en Aabenbarelse og forelagde dem, men de Ansete i Særdeleshed, det Evangelium, som jeg prædiker iblandt Hedningerne, om jeg vel løber eller haver løbet forgjeves."],[2,3,"Men end ikke blev Titus, som var med mig, enddog en Græker, tvungen til at omskæres.","Men end ikke blev Titus, som var med mig, enddog en Græker, tvungen til at omskæres."],[2,4,"Men det skete for de indsnegne falske Brødres Skyld, hvilke have indlistet sig for at bespeide vor Frihed, som vi have i Christus Jesus, paa det de kunde gjøre os til Trælle;","Men det skete for de indsnegne falske Brødres Skyld, hvilke have indlistet sig for at bespeide vor Frihed, som vi have i Christus Jesus, paa det de kunde gjøre os til Trælle;"],[2,5,"hvilke vi ikke noget Øieblik vege med Underdanighed, paa det Evangeliums Sandhed maatte blive varig hos Eder.","hvilke vi ikke noget Øieblik vege med Underdanighed, paa det Evangeliums Sandhed maatte blive varig hos Eder."],[2,6,"Men de, som ansaaes for at være Noget, hvormeget de vare, vedkommer mig ikke, Gud seer ikke paa Menneskens Person;) de Ansete, siger jeg lagde Intet til min Lærdom.","Men de, som ansaaes for at være Noget, hvormeget de vare, vedkommer mig ikke, Gud seer ikke paa Menneskens Person;) de Ansete, siger jeg lagde Intet til min Lærdom."],[2,7,"Men tvertimod, der de saae, at mig var betroet at prædike Evangelium for de Uomskaarne, ligesom Petrus for de Omskaarne,","Men tvertimod, der de saae, at mig var betroet at prædike Evangelium for de Uomskaarne, ligesom Petrus for de Omskaarne,"],[2,8,"(thi han, som gav Petrus Kraft til sit Apostel-Embede hos de Omskaarne, gav ogsaa mig Kraft dertil hos Hedningerne;","(thi han, som gav Petrus Kraft til sit Apostel-Embede hos de Omskaarne, gav ogsaa mig Kraft dertil hos Hedningerne;"],[2,9,"og da de erkjendte den Naade, som mig var given, gave de, nemlig Jakobus og Kephas og Johannes, som ansaaes for Pillere, mig og Barnabas Samfunds-Haand, at vi skulde prædike hos Hedningerne, og de hos de Omskaarne;","og da de erkjendte den Naade, som mig var given, gave de, nemlig Jakobus og Kephas og Johannes, som ansaaes for Pillere, mig og Barnabas Samfunds-Haand, at vi skulde prædike hos Hedningerne, og de hos de Omskaarne;"],[2,10,"kun at vi skulde komme de Fattige ihu, hvilket samme jeg og haver beflittet mig paa at gjøre.","kun at vi skulde komme de Fattige ihu, hvilket samme jeg og haver beflittet mig paa at gjøre."],[2,11,"Men der Petrus kom til Antiochia, modsagde jeg ham lige i Øinene, efterdi han var at laste.","Men der Petrus kom til Antiochia, modsagde jeg ham lige i Øinene, efterdi han var at laste."],[2,12,"Thi førend Nogle fra Jakobus ankom, aad han med Hedningerne; men der de kom, unddrog og fraskilte han sig, af Frygt for dem af Omskærelsen.","Thi førend Nogle fra Jakobus ankom, aad han med Hedningerne; men der de kom, unddrog og fraskilte han sig, af Frygt for dem af Omskærelsen."],[2,13,"Og med ham hyklede ogsaa de andre Jøder, saa at endog Barnabas blev henreven af deres Hykleri.","Og med ham hyklede ogsaa de andre Jøder, saa at endog Barnabas blev henreven af deres Hykleri."],[2,14,"Men der jeg saae, at de ikke vandrede lige efter Evangeliums Sandhed, sagde jeg til Petrus i Alles Paahør: dersom du, som er en Jøde, lever paa hedensk Viis og ikke paa jødisk Viis, hvorfor tvinger du da Hedningerne til at leve paa jødisk Viis?","Men der jeg saae, at de ikke vandrede lige efter Evangeliums Sandhed, sagde jeg til Petrus i Alles Paahør: dersom du, som er en Jøde, lever paa hedensk Viis og ikke paa jødisk Viis, hvorfor tvinger du da Hedningerne til at leve paa jødisk Viis?"],[2,15,"Vi, skjøndt Jøder af Fødsel, og ikke af Hedningerne, Syndere,","Vi, skjøndt Jøder af Fødsel, og ikke af Hedningerne, Syndere,"],[2,16,"efterdi vi vide, at et Menneske ikke bliver retfærdiggjort af Lovens Gjerninger, men ved Jesu Christi Tro, saa have og vi troet paa Jesus Christus, at vi maatte blive retfærdiggjorte af Christi Tro, og ikke af Lovens Gjerninger; thi intet Kjød skal blive retfærdiggjort af Lovens Gjerninger.","efterdi vi vide, at et Menneske ikke bliver retfærdiggjort af Lovens Gjerninger, men ved Jesu Christi Tro, saa have og vi troet paa Jesus Christus, at vi maatte blive retfærdiggjorte af Christi Tro, og ikke af Lovens Gjerninger; thi intet Kjød skal blive retfærdiggjort af Lovens Gjerninger."],[2,17,"Men om vi, idet vi søge at blive retfærdiggjorte i Christus, ogsaa selv befandtes at være Syndere, da var jo Christus Syndens Tjener. Det være langt fra!","Men om vi, idet vi søge at blive retfærdiggjorte i Christus, ogsaa selv befandtes at være Syndere, da var jo Christus Syndens Tjener. Det være langt fra!"],[2,18,"Thi dersom jeg igjen opbygger det Samme, som jeg nedbrød, da viser jeg mig selv at være en Overtræder.","Thi dersom jeg igjen opbygger det Samme, som jeg nedbrød, da viser jeg mig selv at være en Overtræder."],[2,19,"Thi jeg er formedelst Loven død fra Loven, at jeg skal leve Gud.","Thi jeg er formedelst Loven død fra Loven, at jeg skal leve Gud."],[2,20,"Jeg er korsfæstet med Christus; alligevel lever jeg, dog ikke jeg mere, men Christus lever i mig; og hvad jeg nu lever i Kjødet, det lever jeg i Guds Søns Tro, som elskede mig, og gav sig selv hen for mig.","Jeg er korsfæstet med Christus; alligevel lever jeg, dog ikke jeg mere, men Christus lever i mig; og hvad jeg nu lever i Kjødet, det lever jeg i Guds Søns Tro, som elskede mig, og gav sig selv hen for mig."],[2,21,"Jeg agter ikke Guds Naade ringe; thi erholdes Retfærdighed ved Loven, da er jo Christus død forgjeves.","Jeg agter ikke Guds Naade ringe; thi erholdes Retfærdighed ved Loven, da er jo Christus død forgjeves."],[3,1,"O, I uforstandige Galater! hvo haver fortryllet Eder, at I ikke lyde Sandheden? Eder, hvem Jesus Christus var malet for Øine, som korsfæstet iblandt Eder?","O, I uforstandige Galater! hvo haver fortryllet Eder, at I ikke lyde Sandheden? Eder, hvem Jesus Christus var malet for Øine, som korsfæstet iblandt Eder?"],[3,2,"Kun dette vil jeg af Eder: var det ved Lovens Gjerninger, I annammede Aanden, eller ved Troens Forkyndelse?","Kun dette vil jeg af Eder: var det ved Lovens Gjerninger, I annammede Aanden, eller ved Troens Forkyndelse?"],[3,3,"Ere I saa uforstandige? ville I, som begyndte i Aanden, nu fuldende i Kjødet?","Ere I saa uforstandige? ville I, som begyndte i Aanden, nu fuldende i Kjødet?"],[3,4,"Have I da prøvet saa Meget forgjeves? hvis ellers kun forgjeves!","Have I da prøvet saa Meget forgjeves? hvis ellers kun forgjeves!"],[3,5,"Mon da han, som meddeler Eder Aanden og udretter kraftige Gjerninger i Eder, udretter det ved Lovens Gjerninger eller ved Troens Forkyndelse?","Mon da han, som meddeler Eder Aanden og udretter kraftige Gjerninger i Eder, udretter det ved Lovens Gjerninger eller ved Troens Forkyndelse?"],[3,6,"Ligesom Abraham troede Gud, og det blev regnet ham til Retfærdighed.","Ligesom Abraham troede Gud, og det blev regnet ham til Retfærdighed."],[3,7,"Erkjender altsaa, at de, som holde sig til Troen, disse ere Abrahams Børn.","Erkjender altsaa, at de, som holde sig til Troen, disse ere Abrahams Børn."],[3,8,"Men da Skriften forudsaae, at Gud vilde retfærdiggjøre Hedningerne af Troen, forjættede den Abraham forud: i dig skulle alle Folkeslag velsignes.","Men da Skriften forudsaae, at Gud vilde retfærdiggjøre Hedningerne af Troen, forjættede den Abraham forud: i dig skulle alle Folkeslag velsignes."],[3,9,"Saa at de, som holde sig til Troen, blive velsignede med den troende Abraham.","Saa at de, som holde sig til Troen, blive velsignede med den troende Abraham."],[3,10,"Thi saa Mange, som holde sig til Lovens Gjerninger, ere under Forbandelse; thi der er skrevet: forbandet hver den, som ikke bliver ved i alle de Ting, som ere skrevne i Lovens Bog, at han gjør dem.","Thi saa Mange, som holde sig til Lovens Gjerninger, ere under Forbandelse; thi der er skrevet: forbandet hver den, som ikke bliver ved i alle de Ting, som ere skrevne i Lovens Bog, at han gjør dem."],[3,11,"Men at Ingen bliver retfærdiggjort for Gud ved Loven, er aabenbart; thi den Retfærdige ved Troen skal leve.","Men at Ingen bliver retfærdiggjort for Gud ved Loven, er aabenbart; thi den Retfærdige ved Troen skal leve."],[3,12,"Men Loven beroer ikke paa Tro; thi den siger: det Menneske, som gjør disse Ting, skal derved leve.","Men Loven beroer ikke paa Tro; thi den siger: det Menneske, som gjør disse Ting, skal derved leve."],[3,13,"Christus haver frikjøbt os fra Lovens Forbandelse, der han blev en Forbandelse for os; (thi der er skrevet: forbandet er hver den, som hænger paa et Træ;)","Christus haver frikjøbt os fra Lovens Forbandelse, der han blev en Forbandelse for os; (thi der er skrevet: forbandet er hver den, som hænger paa et Træ;)"],[3,14,"paa det Abrahams Velsignelse maatte komme over Hedningerne i Christus Jesus, saa at vi kunde faae Aandens Forjættelse formedelst Troen.","paa det Abrahams Velsignelse maatte komme over Hedningerne i Christus Jesus, saa at vi kunde faae Aandens Forjættelse formedelst Troen."],[3,15,"Brødre! jeg vil tale efter menneskelig Viis: gjør dog Ingen et Menneskes Pagt, som er stadfæstet, til Intet eller sætter Noget dertil.","Brødre! jeg vil tale efter menneskelig Viis: gjør dog Ingen et Menneskes Pagt, som er stadfæstet, til Intet eller sætter Noget dertil."],[3,16,"Men Forjættelserne ere tilsagte Abraham og hans Sæd; der siges ikke: og hans Sæde, som om Mange, men som om Een: og din Sæd, hvilken er Christus.","Men Forjættelserne ere tilsagte Abraham og hans Sæd; der siges ikke: og hans Sæde, som om Mange, men som om Een: og din Sæd, hvilken er Christus."],[3,17,"Dette vil jeg sige: den Pagt, som forud er stadfæstet af Gud om Christus, kan Loven, som blev given fire hundrede og tredive Aar derefter, ikke rykke, at den skulde gjøre Forjættelsen til Intet.","Dette vil jeg sige: den Pagt, som forud er stadfæstet af Gud om Christus, kan Loven, som blev given fire hundrede og tredive Aar derefter, ikke rykke, at den skulde gjøre Forjættelsen til Intet."],[3,18,"Thi er Arven ved Loven, da er den ikke mere ved Forjættelsen; men Gud skjenkede Abraham den ved Forjættelsen.","Thi er Arven ved Loven, da er den ikke mere ved Forjættelsen; men Gud skjenkede Abraham den ved Forjættelsen."],[3,19,"Hvad skal da Loven? Den blev føiet til for Overtrædelsers Skyld, (indtil den Sæd kom, hvem Forjættelsen gjeldte), betjent af Engle, ved en Midlers Haand.","Hvad skal da Loven? Den blev føiet til for Overtrædelsers Skyld, (indtil den Sæd kom, hvem Forjættelsen gjeldte), betjent af Engle, ved en Midlers Haand."],[3,20,"Dog er Midleren ikke Eens, men Gud er een.","Dog er Midleren ikke Eens, men Gud er een."],[3,21,"Er da Loven mod Guds Forjættelser? Det være langt fra! Thi var der givet en Lov, som kunde levendegjøre, da erholdtes Retfærdighed virkeligen ved Loven.","Er da Loven mod Guds Forjættelser? Det være langt fra! Thi var der givet en Lov, som kunde levendegjøre, da erholdtes Retfærdighed virkeligen ved Loven."],[3,22,"Men Skriften haver indesluttet Alt under Synd, at Forjættelsen ved Jesu Christi Tro skulde blive given dem, som troe.","Men Skriften haver indesluttet Alt under Synd, at Forjættelsen ved Jesu Christi Tro skulde blive given dem, som troe."],[3,23,"Men førend Troen kom, bevogtedes vi, indesluttede under Loven, til den Tro, som skulde aabenbares.","Men førend Troen kom, bevogtedes vi, indesluttede under Loven, til den Tro, som skulde aabenbares."],[3,24,"saa at Loven er vorden vor Tugtemester til Christus, at vi skulde blive retfærdiggjorte af Troen.","saa at Loven er vorden vor Tugtemester til Christus, at vi skulde blive retfærdiggjorte af Troen."],[3,25,"Men nu Troen er kommen, ere vi ikke mere under Tugtemesteren.","Men nu Troen er kommen, ere vi ikke mere under Tugtemesteren."],[3,26,"I ere jo alle Guds Børn formedelst Troen i Christus Jesus.","I ere jo alle Guds Børn formedelst Troen i Christus Jesus."],[3,27,"Thi I, saa mange som ere døbte til Christus, have iført Christus.","Thi I, saa mange som ere døbte til Christus, have iført Christus."],[3,28,"Her er ikke Jøde eller Græker; her er ikke Træl eller Fri; her er ikke Mand eller Kvinde; thi I ere alle Een i Christus Jesus.","Her er ikke Jøde eller Græker; her er ikke Træl eller Fri; her er ikke Mand eller Kvinde; thi I ere alle Een i Christus Jesus."],[3,29,"Men ere i Christi, da ere i jo Abrahams Sæd og Arvinger efter Forjættelsen.","Men ere i Christi, da ere i jo Abrahams Sæd og Arvinger efter Forjættelsen."],[4,1,"Men jeg siger: saa længe Arvingen er et Barn, er der ingen Forskjel mellem ham og Trællen, enddog han er Herre over alt Godset:","Men jeg siger: saa længe Arvingen er et Barn, er der ingen Forskjel mellem ham og Trællen, enddog han er Herre over alt Godset:"],[4,2,"men han er under Formyndere og Huusholdere indtil den af Faderen bestemte Tid.","men han er under Formyndere og Huusholdere indtil den af Faderen bestemte Tid."],[4,3,"Saaledes stode og vi, saalænge vi vare Børn, som Trælle under Verdens Børnelærdom.","Saaledes stode og vi, saalænge vi vare Børn, som Trælle under Verdens Børnelærdom."],[4,4,"Men der Tidens Fylde kom, udsendte Gud sin Søn, født af en Kvinde, født under Loven,","Men der Tidens Fylde kom, udsendte Gud sin Søn, født af en Kvinde, født under Loven,"],[4,5,"paa det han skulde frikjøbe dem, som vare under Loven, at vi skulde faae den sønlige Udkaarelse,","paa det han skulde frikjøbe dem, som vare under Loven, at vi skulde faae den sønlige Udkaarelse,"],[4,6,"Eftersom I da ere Sønner, haver Gud udsendt sin Søns Aand i Eders Hjerter, som raaber: Abba, Fader!","Eftersom I da ere Sønner, haver Gud udsendt sin Søns Aand i Eders Hjerter, som raaber: Abba, Fader!"],[4,7,"Saa at du ikke længer er Træl, men Søn; men er du Søn, da er du ogsaa Guds Arving formedelst Christus.","Saa at du ikke længer er Træl, men Søn; men er du Søn, da er du ogsaa Guds Arving formedelst Christus."],[4,8,"Vel sandt, dengang da I ikke kjendte Gud, tjente I dem, som ei af Væsen ere Guder.","Vel sandt, dengang da I ikke kjendte Gud, tjente I dem, som ei af Væsen ere Guder."],[4,9,"Men nu, da I kjende Gud, ja, meget mere ere kjendte af Gud, hvorledes vende I da atter tilbage til den svage og fattige Børnelærdom, hvoraf I atter forfra ville gjøre Eder til Trælle?","Men nu, da I kjende Gud, ja, meget mere ere kjendte af Gud, hvorledes vende I da atter tilbage til den svage og fattige Børnelærdom, hvoraf I atter forfra ville gjøre Eder til Trælle?"],[4,10,"I tage vare paa Dage og Maaneder og Tider og Aar.","I tage vare paa Dage og Maaneder og Tider og Aar."],[4,11,"Jeg frygter for Eder, at jeg maaskee haver arbeidet forgjeves paa Eder.","Jeg frygter for Eder, at jeg maaskee haver arbeidet forgjeves paa Eder."],[4,12,"Vorder ligesom jeg, thi jeg er som I, Brødre! jeg beder Eder: I have ingen Uret gjort mig.","Vorder ligesom jeg, thi jeg er som I, Brødre! jeg beder Eder: I have ingen Uret gjort mig."],[4,13,"Men I vide, at jeg under Kjødets Skrøbelighed første Gang prædikede Eder Evangelium;","Men I vide, at jeg under Kjødets Skrøbelighed første Gang prædikede Eder Evangelium;"],[4,14,"og for denne Prøvelse i mit Kjød ringeagtede I mig ikke og forhaanede mig ikke, men I annammede mig som en Guds Engel, som Christus Jesus.","og for denne Prøvelse i mit Kjød ringeagtede I mig ikke og forhaanede mig ikke, men I annammede mig som en Guds Engel, som Christus Jesus."],[4,15,"Hvor prisede I Eder da salige! Thi jeg giver Eder det Vidnesbyrd, at, om det havde været muligt, havde I udrevet Eders Øine og givet mig.","Hvor prisede I Eder da salige! Thi jeg giver Eder det Vidnesbyrd, at, om det havde været muligt, havde I udrevet Eders Øine og givet mig."],[4,16,"Et jeg da nu bleven Eders Fjende, fordi jeg siger Eder Sandheden?","Et jeg da nu bleven Eders Fjende, fordi jeg siger Eder Sandheden?"],[4,17,"De ere nidkjære for Eder, dog ikke til det Bedste; men de ville udelukke Eder, at I skulle være nidkjære efter dem.","De ere nidkjære for Eder, dog ikke til det Bedste; men de ville udelukke Eder, at I skulle være nidkjære efter dem."],[4,18,"Men det er godt at være nidkjær i det Gode altid, og ikke alene, naar jeg er nærværende hos Eder.","Men det er godt at være nidkjær i det Gode altid, og ikke alene, naar jeg er nærværende hos Eder."],[4,19,"Mine Børn, hvilke jeg atter føder med Smerte, indtil Christus faaer sin Skikkelse i Eder!","Mine Børn, hvilke jeg atter føder med Smerte, indtil Christus faaer sin Skikkelse i Eder!"],[4,20,"Gid jeg nu var tilstede hos Eder, og kunde omskifte min Røst ; thi jeg er tvivlraadig om Eder.","Gid jeg nu var tilstede hos Eder, og kunde omskifte min Røst ; thi jeg er tvivlraadig om Eder."],[4,21,"Siger mig, I som ville være under Loven, høre I ikke Loven?","Siger mig, I som ville være under Loven, høre I ikke Loven?"],[4,22,"Der er jo skrevet, at Abraham havde to Sønner, een af Tjenestekvinden og een af den frie Kvinde.","Der er jo skrevet, at Abraham havde to Sønner, een af Tjenestekvinden og een af den frie Kvinde."],[4,23,"Men den af Tjenestekvinden var født efter Kjødet, den af den frie Kvinde efter Forjættelsen.","Men den af Tjenestekvinden var født efter Kjødet, den af den frie Kvinde efter Forjættelsen."],[4,24,"Dette tyder paa noget Høiere. Thi disse ere de tvende Pagter, den ene fra Sinai Bjerg, som føder til Trældom: denne er Hagar.","Dette tyder paa noget Høiere. Thi disse ere de tvende Pagter, den ene fra Sinai Bjerg, som føder til Trældom: denne er Hagar."],[4,25,"Thi Hagar er Sinai Bjerg i Arabia og svarer til det Jerusalem, som nu er og er i Trældom med sine Børn.","Thi Hagar er Sinai Bjerg i Arabia og svarer til det Jerusalem, som nu er og er i Trældom med sine Børn."],[4,26,"Men det Jerusalem heroventil er den frie Kvinde, som er alle vores Moder.","Men det Jerusalem heroventil er den frie Kvinde, som er alle vores Moder."],[4,27,"Thi der er skrevet: vær glad, du Ufrugtbare, du, som ikke fødte! udbryd og raab, du som ikke havde Fødselssmerte! thi den Forladtes Børn ere meget flere end dens, som haver Manden.","Thi der er skrevet: vær glad, du Ufrugtbare, du, som ikke fødte! udbryd og raab, du som ikke havde Fødselssmerte! thi den Forladtes Børn ere meget flere end dens, som haver Manden."],[4,28,"Men vi, Brødre! ere Forjættelsens Børn, som Isaak var.","Men vi, Brødre! ere Forjættelsens Børn, som Isaak var."],[4,29,"Ligesom dengang han, som var født efter Kjødet, forfulgte den, som var Født efter Aanden, saaledes ogsaa nu.","Ligesom dengang han, som var født efter Kjødet, forfulgte den, som var Født efter Aanden, saaledes ogsaa nu."],[4,30,"Men hvad siger Skriften? Udstød Tjenestekvinden og hendes Søn; thi Tjenestekvindens Søn skal ingenlunde arve med den frie Kvindes Søn.","Men hvad siger Skriften? Udstød Tjenestekvinden og hendes Søn; thi Tjenestekvindens Søn skal ingenlunde arve med den frie Kvindes Søn."],[4,31,"Saa ere vi da, Brødre! ikke Tjenestekvindens Børn, men den frie Kvindes.","Saa ere vi da, Brødre! ikke Tjenestekvindens Børn, men den frie Kvindes."],[5,1,"Derfor bliver stadige i den Frihed, hvormed Christus frigjorde os, og lader Eder ikke atter tvinge under Trældoms Aag.","Derfor bliver stadige i den Frihed, hvormed Christus frigjorde os, og lader Eder ikke atter tvinge under Trældoms Aag."],[5,2,"See, jeg Paulus siger Eder, at dersom I lade Eder omskære, nytter Christus Eder Intet.","See, jeg Paulus siger Eder, at dersom I lade Eder omskære, nytter Christus Eder Intet."],[5,3,"Jeg vidner atter for hvert Menneske, som lader sig omskære, at han er skyldig til at holde den ganske Lov.","Jeg vidner atter for hvert Menneske, som lader sig omskære, at han er skyldig til at holde den ganske Lov."],[5,4,"I have Intet med Christus at gjøre, I, som ville retfærdiggjøres ved Loven; I ere faldne fra Naaden.","I have Intet med Christus at gjøre, I, som ville retfærdiggjøres ved Loven; I ere faldne fra Naaden."],[5,5,"Thi vi vente i Aanden ved Troen den forhaabede Retfærdighed.","Thi vi vente i Aanden ved Troen den forhaabede Retfærdighed."],[5,6,"Thi i Christus Jesus gjelder hverken Omskærelse eller Forhud, men Troen, som er virksom ved Kjærlighed.","Thi i Christus Jesus gjelder hverken Omskærelse eller Forhud, men Troen, som er virksom ved Kjærlighed."],[5,7,"I vare paa god Vei; hvo standsede Eder, saa at I ikke lade Eder overtales af Sandheden?","I vare paa god Vei; hvo standsede Eder, saa at I ikke lade Eder overtales af Sandheden?"],[5,8,"Den Overtalelse er ikke fra ham, som kaldte Eder.","Den Overtalelse er ikke fra ham, som kaldte Eder."],[5,9,"En liden Suurdeig gjør den ganske Dei suur.","En liden Suurdeig gjør den ganske Dei suur."],[5,10,"Jeg haver den Tillid til Eder i Herren, at I intet andet ville mene; men den, som forvilder Eder, skal lide Dommen, hvo han end er.","Jeg haver den Tillid til Eder i Herren, at I intet andet ville mene; men den, som forvilder Eder, skal lide Dommen, hvo han end er."],[5,11,"Men jeg, Brødre! dersom jeg endnu prædiker Omskærelse, hvi forfølges jeg endnu? Da var Korsets Forargelse borttagen.","Men jeg, Brødre! dersom jeg endnu prædiker Omskærelse, hvi forfølges jeg endnu? Da var Korsets Forargelse borttagen."],[5,12,"Gid de og maatte afskæres, som forvirre Eder!","Gid de og maatte afskæres, som forvirre Eder!"],[5,13,"I ere jo kaldte til Frihed, Brødre! kun misbruger ikke Friheden til en Anledning for Kjødet, men værer i Kjærlighed hverandres Tjenere.","I ere jo kaldte til Frihed, Brødre! kun misbruger ikke Friheden til en Anledning for Kjødet, men værer i Kjærlighed hverandres Tjenere."],[5,14,"Thi al Loven fuldkommes i eet Bud, nemlig i det: du skal elske din Næste som dig selv.","Thi al Loven fuldkommes i eet Bud, nemlig i det: du skal elske din Næste som dig selv."],[5,15,"Men dersom I bide og æde hverandre, da seer til, at I ikke fortæres af hverandre.","Men dersom I bide og æde hverandre, da seer til, at I ikke fortæres af hverandre."],[5,16,"Dette siger jeg: vandrer i Aanden, saa skulde I ikke fuldkomme Kjødets Begjering.","Dette siger jeg: vandrer i Aanden, saa skulde I ikke fuldkomme Kjødets Begjering."],[5,17,"Thi Kjødet begjerer imod Aanden, men Aanden imod Kjødet; og disse ere hinanden modsatte, saa at I ikke kunne gjøre, hvad I ville.","Thi Kjødet begjerer imod Aanden, men Aanden imod Kjødet; og disse ere hinanden modsatte, saa at I ikke kunne gjøre, hvad I ville."],[5,18,"Men dersom I drives af Aanden, ere I ikke under Loven.","Men dersom I drives af Aanden, ere I ikke under Loven."],[5,19,"Kjødets Gjerninger ere aabenbare, saasom: Hoer, Skjørlevnet, Ureenhed, Uteerlighed,","Kjødets Gjerninger ere aabenbare, saasom: Hoer, Skjørlevnet, Ureenhed, Uteerlighed,"],[5,20,"Afgudsdyrkelse, Trolddom, Fjendskaber, Kiv, Nid, Vrede, Trætte, Tvedragt, Partier,","Afgudsdyrkelse, Trolddom, Fjendskaber, Kiv, Nid, Vrede, Trætte, Tvedragt, Partier,"],[5,21,"Avind, Mord, Drukkenskab, Fraadseri og deslige; om hvilke jeg forud siger Eder, ligesom jeg og før haver sagt, at de, som gjøre Saadant, skulle ikke arve Guds Rige.","Avind, Mord, Drukkenskab, Fraadseri og deslige; om hvilke jeg forud siger Eder, ligesom jeg og før haver sagt, at de, som gjøre Saadant, skulle ikke arve Guds Rige."],[5,22,"Men Aandens Frugt er Kjærlighed, Glæde, Fred, Langmodighed, Mildhed, Godhed, Trofasthed, Sagtmodighed, Afholdenhed.","Men Aandens Frugt er Kjærlighed, Glæde, Fred, Langmodighed, Mildhed, Godhed, Trofasthed, Sagtmodighed, Afholdenhed."],[5,23,"Mod Saadanne er Loven ikke.","Mod Saadanne er Loven ikke."],[5,24,"Men de, som høre Christus til, have korsfæstet Kjødet med Lysterne og Begjeringerne.","Men de, som høre Christus til, have korsfæstet Kjødet med Lysterne og Begjeringerne."],[5,25,"Dersom vi leve i Aanden, da lader os og gaae frem i Aanden.","Dersom vi leve i Aanden, da lader os og gaae frem i Aanden."],[5,26,"Lader os ikke have Lyst til forfængelig Ære, saa at vi vil trodse hverandre og bære Avind imod hverandre.","Lader os ikke have Lyst til forfængelig Ære, saa at vi vil trodse hverandre og bære Avind imod hverandre."],[6,1,"Brødre: dersom og et Menneske bliver overilet af nogen Brøst, da hjælper ham tilrette, I Aandelige! med Sagtmodigheds Aand; men see til dig selv, at ikke og du bliver fristet.","Brødre: dersom og et Menneske bliver overilet af nogen Brøst, da hjælper ham tilrette, I Aandelige! med Sagtmodigheds Aand; men see til dig selv, at ikke og du bliver fristet."],[6,2,"Bærer hverandres Byrde, og opfylder saaledes Christi Lov.","Bærer hverandres Byrde, og opfylder saaledes Christi Lov."],[6,3,"Thi dersom Nogen tykkes sig at være Noget, og er dog Intet, han bedrager sig selv.","Thi dersom Nogen tykkes sig at være Noget, og er dog Intet, han bedrager sig selv."],[6,4,"Men hver prøve sin egen Gjerning, og da skal han have Roes for sig selv alene, og ikke for Andre;","Men hver prøve sin egen Gjerning, og da skal han have Roes for sig selv alene, og ikke for Andre;"],[6,5,"thi hver skal bære sin egen Byrde.","thi hver skal bære sin egen Byrde."],[6,6,"Men den, som undervises i Ordet, skal dele alt Godt med den, som ham underviser.","Men den, som undervises i Ordet, skal dele alt Godt med den, som ham underviser."],[6,7,"Farer ikke vild; Gud lader sig ikke spotte; thi hvad et Menneske saaer, dette skal han og høste.","Farer ikke vild; Gud lader sig ikke spotte; thi hvad et Menneske saaer, dette skal han og høste."],[6,8,"Thi hvo som saaer i sit Kjød, skal høste Forkrænkelse af Kjødet; men hvo som saaer i Aanden, skal høste det evige Liv af Aanden.","Thi hvo som saaer i sit Kjød, skal høste Forkrænkelse af Kjødet; men hvo som saaer i Aanden, skal høste det evige Liv af Aanden."],[6,9,"Men naar vi gjøre det Gode, lader os ikke blive trætte; thi vi skulle og høste i sin Tid, saafremt vi ikke forsage.","Men naar vi gjøre det Gode, lader os ikke blive trætte; thi vi skulle og høste i sin Tid, saafremt vi ikke forsage."],[6,10,"Derfor, eftersom vi have Leilighed, lader os gjøre det Gode mod Alle, men meest mod Troens Egne.","Derfor, eftersom vi have Leilighed, lader os gjøre det Gode mod Alle, men meest mod Troens Egne."],[6,11,"Seer, hvilket langt Brev jeg har skrevet Eder til med min egen Haand.","Seer, hvilket langt Brev jeg har skrevet Eder til med min egen Haand."],[6,12,"De, som ville have Anseelse efter Kjødet, tvinge Eder til at omskæres, alene paa det de ikke skulle forfølges formedelst Christi Kors.","De, som ville have Anseelse efter Kjødet, tvinge Eder til at omskæres, alene paa det de ikke skulle forfølges formedelst Christi Kors."],[6,13,"Thi end ikke de Omskaarne holde selv Loven; men de ville, at I skulle omskæres, paa det de kunne rose sig af Eders Kjød.","Thi end ikke de Omskaarne holde selv Loven; men de ville, at I skulle omskæres, paa det de kunne rose sig af Eders Kjød."],[6,14,"Men det være langt fra mig at rose mig, uden at vor Herres Jesu Christi Kors, formedelst hvem Verden er mig korsfæstet, og jeg Verden.","Men det være langt fra mig at rose mig, uden at vor Herres Jesu Christi Kors, formedelst hvem Verden er mig korsfæstet, og jeg Verden."],[6,15,"Thi i Christus Jesus gjælder hverken Omskærelse eller Forhud Noget, men en ny Skabning.","Thi i Christus Jesus gjælder hverken Omskærelse eller Forhud Noget, men en ny Skabning."],[6,16,"Og saa Mange, som gaae frem efter denne Regel, over dem, være Fred og Barmhjertighed, og over Guds Israel.","Og saa Mange, som gaae frem efter denne Regel, over dem, være Fred og Barmhjertighed, og over Guds Israel."],[6,17,"Iøvrigt volde Ingen mig Besvær; thi jeg bærer den Herres Jesu Mærketegn paa mit Legeme.","Iøvrigt volde Ingen mig Besvær; thi jeg bærer den Herres Jesu Mærketegn paa mit Legeme."],[6,18,"Vor Herres Jesu Christi Naade være med Eders Aand, Brødre! Amen.","Vor Herres Jesu Christi Naade være med Eders Aand, Brødre! Amen."]],"epo-londona":[[1,1,"Paŭlo, apostolo (ne de homoj, nek per homo, sed per Jesuo Kristo, kaj Dio, la Patro, kiu levis lin el la mortintoj),","Paŭlo, apostolo (ne de homoj, nek per homo, sed per Jesuo Kristo, kaj Dio, la Patro, kiu levis lin el la mortintoj),"],[1,2,"kaj ĉiuj fratoj, kiuj estas kun mi, al la eklezioj de Galatujo:","kaj ĉiuj fratoj, kiuj estas kun mi, al la eklezioj de Galatujo:"],[1,3,"Graco al vi kaj paco de Dio, la Patro, kaj de nia Sinjoro Jesuo Kristo,","Graco al vi kaj paco de Dio, la Patro, kaj de nia Sinjoro Jesuo Kristo,"],[1,4,"kiu sin donis pro niaj pekoj, por liberigi nin el la nuna malbona mondo, laŭ la volo de nia Dio kaj Patro;","kiu sin donis pro niaj pekoj, por liberigi nin el la nuna malbona mondo, laŭ la volo de nia Dio kaj Patro;"],[1,5,"al kiu estu la gloro por ĉiam kaj eterne. Amen.","al kiu estu la gloro por ĉiam kaj eterne. Amen."],[1,6,"Mi miras, ke tiel rapide vi foriĝas for de Tiu, kiu vokis vin en la gracon de Kristo, al malsama evangelio;","Mi miras, ke tiel rapide vi foriĝas for de Tiu, kiu vokis vin en la gracon de Kristo, al malsama evangelio;"],[1,7,"kiu ja ne estas alia, sed troviĝas iuj, kiuj vin maltrankviligas kaj deziras renversi la evangelion de Kristo.","kiu ja ne estas alia, sed troviĝas iuj, kiuj vin maltrankviligas kaj deziras renversi la evangelion de Kristo."],[1,8,"Tamen se eĉ ni, aŭ anĝelo el la ĉielo, al vi instruus ian evangelion krom tiu, kiun ni jam al vi instruis, tiu estu anatemita.","Tamen se eĉ ni, aŭ anĝelo el la ĉielo, al vi instruus ian evangelion krom tiu, kiun ni jam al vi instruis, tiu estu anatemita."],[1,9,"Kiel ni antaŭe diris, tiel nun mi denove diras: Se iu al vi instruas ian evangelion krom tiu, kiun vi ricevis, tiu estu anatemita.","Kiel ni antaŭe diris, tiel nun mi denove diras: Se iu al vi instruas ian evangelion krom tiu, kiun vi ricevis, tiu estu anatemita."],[1,10,"Ĉar ĉu mi nun influas homojn, aŭ Dion? aŭ ĉu mi celas plaĉi al homoj? se mi ankoraŭ nun plaĉus al homoj, mi ne estus servisto de Kristo.","Ĉar ĉu mi nun influas homojn, aŭ Dion? aŭ ĉu mi celas plaĉi al homoj? se mi ankoraŭ nun plaĉus al homoj, mi ne estus servisto de Kristo."],[1,11,"Ĉar mi sciigas vin, fratoj, rilate al la evangelio predikita de mi, ke ĝi ne estas laŭ homo.","Ĉar mi sciigas vin, fratoj, rilate al la evangelio predikita de mi, ke ĝi ne estas laŭ homo."],[1,12,"Ĉar mi ne ricevis ĝin de homo, kaj ĝi ne estas instruita al mi krom per malkaŝo de Jesuo Kristo.","Ĉar mi ne ricevis ĝin de homo, kaj ĝi ne estas instruita al mi krom per malkaŝo de Jesuo Kristo."],[1,13,"Ĉar vi iam aŭdis pri mia estinta vivmaniero en Judismo, ke mi forte persekutis la eklezion de Dio kaj ĝin atakis;","Ĉar vi iam aŭdis pri mia estinta vivmaniero en Judismo, ke mi forte persekutis la eklezion de Dio kaj ĝin atakis;"],[1,14,"kaj mi plimulte progresis en Judismo, ol multaj miaj samaĝuloj en mia nacio, estante multe pli fervoranima pri la tradicioj de miaj prapatroj.","kaj mi plimulte progresis en Judismo, ol multaj miaj samaĝuloj en mia nacio, estante multe pli fervoranima pri la tradicioj de miaj prapatroj."],[1,15,"Sed kiam bonvole plaĉis al Dio, kiu el la ventro de mia patrino apartigis min kaj per Sia graco min vokis,","Sed kiam bonvole plaĉis al Dio, kiu el la ventro de mia patrino apartigis min kaj per Sia graco min vokis,"],[1,16,"por malkaŝi en mi Sian Filon, por ke mi prediku lin inter la nacianoj: mi ne konsiliĝis kun karno kaj sango,","por malkaŝi en mi Sian Filon, por ke mi prediku lin inter la nacianoj: mi ne konsiliĝis kun karno kaj sango,"],[1,17,"kaj mi ne supreniris al Jerusalem, al la antaŭ mi apostoloj, sed mi tuj foriris en Arabujon, kaj poste mi revenis al Damasko.","kaj mi ne supreniris al Jerusalem, al la antaŭ mi apostoloj, sed mi tuj foriris en Arabujon, kaj poste mi revenis al Damasko."],[1,18,"Tiam, post tri jaroj, mi supreniris al Jerusalem, por viziti Kefason, kaj mi restis kun li dek kvin tagojn.","Tiam, post tri jaroj, mi supreniris al Jerusalem, por viziti Kefason, kaj mi restis kun li dek kvin tagojn."],[1,19,"Sed neniun alian el la apostoloj mi vidis, krom Jakobo, la frato de la Sinjoro.","Sed neniun alian el la apostoloj mi vidis, krom Jakobo, la frato de la Sinjoro."],[1,20,"Pri tio, kion mi skribas al vi, jen, antaŭ Dio, mi ne mensogas.","Pri tio, kion mi skribas al vi, jen, antaŭ Dio, mi ne mensogas."],[1,21,"Poste mi venis en la regionojn de Sirio kaj Kilikio.","Poste mi venis en la regionojn de Sirio kaj Kilikio."],[1,22,"Kaj mi ankoraŭ estis vizaĝe nekonata de la eklezioj de Judujo, kiuj estis en Kristo;","Kaj mi ankoraŭ estis vizaĝe nekonata de la eklezioj de Judujo, kiuj estis en Kristo;"],[1,23,"sed ili nur aŭdis la jenon: Kiu nin iam persekutis, tiu nun predikas la fidon, kiun iam li atakis;","sed ili nur aŭdis la jenon: Kiu nin iam persekutis, tiu nun predikas la fidon, kiun iam li atakis;"],[1,24,"kaj ili gloris Dion en mi.","kaj ili gloris Dion en mi."],[2,1,"Tiam, post intertempo de dek kvar jaroj, mi denove supreniris al Jerusalem kun Barnabas, kunkondukante ankaŭ Titon.","Tiam, post intertempo de dek kvar jaroj, mi denove supreniris al Jerusalem kun Barnabas, kunkondukante ankaŭ Titon."],[2,2,"Kaj mi supreniris laŭ Dia malkaŝo; kaj mi prezentis al ili la evangelion, kiun mi predikas inter la nacianoj, sed aparte al la eminentuloj, por ke mi ne estu vane kuranta, aŭ kurinta.","Kaj mi supreniris laŭ Dia malkaŝo; kaj mi prezentis al ili la evangelion, kiun mi predikas inter la nacianoj, sed aparte al la eminentuloj, por ke mi ne estu vane kuranta, aŭ kurinta."],[2,3,"Sed eĉ Titon, kiu estis kun mi, estante Greko, oni ne devigis cirkumcidiĝi;","Sed eĉ Titon, kiu estis kun mi, estante Greko, oni ne devigis cirkumcidiĝi;"],[2,4,"sed tio estis pro la kaŝe enportitaj fratoj, kiuj ruze envenis, por spioni nian liberecon en Kristo Jesuo, por ke ili nin sklavigu;","sed tio estis pro la kaŝe enportitaj fratoj, kiuj ruze envenis, por spioni nian liberecon en Kristo Jesuo, por ke ili nin sklavigu;"],[2,5,"al kiuj ni ne submetiĝis cedeme, eĉ por unu horo; por ke la vero de la evangelio restadu kun vi.","al kiuj ni ne submetiĝis cedeme, eĉ por unu horo; por ke la vero de la evangelio restadu kun vi."],[2,6,"Sed el tiuj, kiuj ŝajne iom valoris (kiaj ajn ili estis, tio por mi ne estas grava: ĉe Dio ne estas personfavorado) — tiuj valoruloj nenion aldonis al mi;","Sed el tiuj, kiuj ŝajne iom valoris (kiaj ajn ili estis, tio por mi ne estas grava: ĉe Dio ne estas personfavorado) — tiuj valoruloj nenion aldonis al mi;"],[2,7,"sed kontraŭe, kiam ili vidis, ke je la evangelio de la necirkumcido mi estas komisiita tiel same, kiel Petro je la evangelio de la cirkumcido","sed kontraŭe, kiam ili vidis, ke je la evangelio de la necirkumcido mi estas komisiita tiel same, kiel Petro je la evangelio de la cirkumcido"],[2,8,"(ĉar Tiu, kiu forte energiis en Petro por la apostoleco de la cirkumcido, ankaŭ energiis en mi por la nacianoj),","(ĉar Tiu, kiu forte energiis en Petro por la apostoleco de la cirkumcido, ankaŭ energiis en mi por la nacianoj),"],[2,9,"Jakobo kaj Kefas kaj Johano, kiuj ŝajne estis kolonoj, rimarkinte la gracon donitan al mi, donis al mi kaj al Barnabas la dekstrajn manojn de kunuleco, por ke ni iru al la nacianoj, kaj ili al la cirkumcidularo;","Jakobo kaj Kefas kaj Johano, kiuj ŝajne estis kolonoj, rimarkinte la gracon donitan al mi, donis al mi kaj al Barnabas la dekstrajn manojn de kunuleco, por ke ni iru al la nacianoj, kaj ili al la cirkumcidularo;"],[2,10,"kondiĉe nur, ke ni memoru la malriĉulojn, kion ja mi klopodis jam fari.","kondiĉe nur, ke ni memoru la malriĉulojn, kion ja mi klopodis jam fari."],[2,11,"Sed kiam venis Kefas al Antioĥia, mi lin rezistis vizaĝon kontraŭ vizaĝo, ĉar li estis mallaŭdinda.","Sed kiam venis Kefas al Antioĥia, mi lin rezistis vizaĝon kontraŭ vizaĝo, ĉar li estis mallaŭdinda."],[2,12,"Ĉar antaŭ ol iuj alvenis de Jakobo, li kunmanĝis kun la nacianoj; sed kiam ili alvenis, li sin fortiris kaj apartigis, timante tiujn, kiuj estis el la cirkumcido.","Ĉar antaŭ ol iuj alvenis de Jakobo, li kunmanĝis kun la nacianoj; sed kiam ili alvenis, li sin fortiris kaj apartigis, timante tiujn, kiuj estis el la cirkumcido."],[2,13,"Kaj la aliaj Judoj kune hipokritis, tiel ke eĉ Barnabas mem fortiriĝis per ilia hipokriteco.","Kaj la aliaj Judoj kune hipokritis, tiel ke eĉ Barnabas mem fortiriĝis per ilia hipokriteco."],[2,14,"Kaj kiam mi vidis, ke ili ne prave kondutas laŭ la vero de la evangelio, mi diris al Kefas antaŭ ĉiuj: Se vi, estante Judo, naciane vivas, kaj ne kiel Judoj, kial vi devigas la nacianojn agi laŭ Judismo?","Kaj kiam mi vidis, ke ili ne prave kondutas laŭ la vero de la evangelio, mi diris al Kefas antaŭ ĉiuj: Se vi, estante Judo, naciane vivas, kaj ne kiel Judoj, kial vi devigas la nacianojn agi laŭ Judismo?"],[2,15,"Ni, nature Judoj, kaj ne pekuloj el la nacianoj,","Ni, nature Judoj, kaj ne pekuloj el la nacianoj,"],[2,16,"sciante, ke praviĝas homo ne per faroj de la leĝo, sed nur per fido al Jesuo Kristo, ni mem en Kristo Jesuo kredis, por ke ni praviĝu per fido al Kristo, kaj ne per faroj de la leĝo; tial, ke per faroj de la leĝo neniu karno praviĝos.","sciante, ke praviĝas homo ne per faroj de la leĝo, sed nur per fido al Jesuo Kristo, ni mem en Kristo Jesuo kredis, por ke ni praviĝu per fido al Kristo, kaj ne per faroj de la leĝo; tial, ke per faroj de la leĝo neniu karno praviĝos."],[2,17,"Sed se, dezirante praviĝi en Kristo, ni mem montriĝis pekuloj, ĉu Kristo estas servanto de peko? Nepre ne!","Sed se, dezirante praviĝi en Kristo, ni mem montriĝis pekuloj, ĉu Kristo estas servanto de peko? Nepre ne!"],[2,18,"Ĉar se mi rekonstruas tion, kion mi detruis, mi montras min pekulo.","Ĉar se mi rekonstruas tion, kion mi detruis, mi montras min pekulo."],[2,19,"Ĉar per la leĝo mi al la leĝo mortis, por ke mi al Dio vivu.","Ĉar per la leĝo mi al la leĝo mortis, por ke mi al Dio vivu."],[2,20,"Kun Kristo mi krucumiĝis, tamen mi vivas; jam ne mi mem, sed Kristo vivas en mi; kaj tiun vivon, kiun mi vivas en karno, mi vivas en fido al la Filo de Dio, kiu min amis kaj sin donis pro mi.","Kun Kristo mi krucumiĝis, tamen mi vivas; jam ne mi mem, sed Kristo vivas en mi; kaj tiun vivon, kiun mi vivas en karno, mi vivas en fido al la Filo de Dio, kiu min amis kaj sin donis pro mi."],[2,21,"Mi ne vanigas la gracon de Dio; ĉar se per la leĝo venas justeco, Kristo ja vane mortis.","Mi ne vanigas la gracon de Dio; ĉar se per la leĝo venas justeco, Kristo ja vane mortis."],[3,1,"Ho malsaĝaj Galatoj, kiu vin ensorĉis? vin, antaŭ kies okuloj Kristo Jesuo estis publike prezentita krucumita.","Ho malsaĝaj Galatoj, kiu vin ensorĉis? vin, antaŭ kies okuloj Kristo Jesuo estis publike prezentita krucumita."],[3,2,"Nur la jenon mi deziras sciiĝi de vi: Ĉu per faroj de la leĝo vi ricevis la Spiriton, aŭ per la aŭdado de fido?","Nur la jenon mi deziras sciiĝi de vi: Ĉu per faroj de la leĝo vi ricevis la Spiriton, aŭ per la aŭdado de fido?"],[3,3,"Ĉu vi tiel malsaĝaj estas? komencinte en Spirito, ĉu vi en karno nun perfektiĝas?","Ĉu vi tiel malsaĝaj estas? komencinte en Spirito, ĉu vi en karno nun perfektiĝas?"],[3,4,"Ĉu vi vane tiom suferis? se ja tio estas vana.","Ĉu vi vane tiom suferis? se ja tio estas vana."],[3,5,"Ĉu do Tiu, kiu donas al vi la Spiriton kaj faras ĉe vi miraklojn, tion faras per faroj de la leĝo, aŭ per la aŭdado de fido?","Ĉu do Tiu, kiu donas al vi la Spiriton kaj faras ĉe vi miraklojn, tion faras per faroj de la leĝo, aŭ per la aŭdado de fido?"],[3,6,"Tiel same, kiel Abraham kredis al Dio, kaj tio estis kalkulita al li kiel virto.","Tiel same, kiel Abraham kredis al Dio, kaj tio estis kalkulita al li kiel virto."],[3,7,"Sciu do, ke tiuj, kiuj rilatas al fido, estas filoj de Abraham.","Sciu do, ke tiuj, kiuj rilatas al fido, estas filoj de Abraham."],[3,8,"Antaŭvidante do, ke per fido Dio pravigos la nacianojn, la Skribo antaŭpredikis la evangelion al Abraham, dirante: Beniĝos per vi ĉiuj gentoj.","Antaŭvidante do, ke per fido Dio pravigos la nacianojn, la Skribo antaŭpredikis la evangelion al Abraham, dirante: Beniĝos per vi ĉiuj gentoj."],[3,9,"Tial do tiuj, kiuj rilatas al fido, beniĝas kun la fidela Abraham.","Tial do tiuj, kiuj rilatas al fido, beniĝas kun la fidela Abraham."],[3,10,"Ĉar ĉiuj, kiuj rilatas al faroj de la leĝo, estas sub malbeno; ĉar estas skribite: Malbenita estas ĉiu, kiu ne persistos en ĉio, kio estas skribita en la libro de la leĝo, por plenumi ĝin.","Ĉar ĉiuj, kiuj rilatas al faroj de la leĝo, estas sub malbeno; ĉar estas skribite: Malbenita estas ĉiu, kiu ne persistos en ĉio, kio estas skribita en la libro de la leĝo, por plenumi ĝin."],[3,11,"Sed ke neniu praviĝas antaŭ Dio per la leĝo, estas evidente; ĉar: La virtulo vivos per fido;","Sed ke neniu praviĝas antaŭ Dio per la leĝo, estas evidente; ĉar: La virtulo vivos per fido;"],[3,12,"kaj la leĝo ne rilatas al fido; sed: Kiu plenumas ilin, tiu vivos en ili.","kaj la leĝo ne rilatas al fido; sed: Kiu plenumas ilin, tiu vivos en ili."],[3,13,"Kristo elaĉetis nin el la malbeno de la leĝo, fariĝinte malbeno pro ni; ĉar estas skribite: Malbenita estas ĉiu, kiu pendas sur lignaĵo;","Kristo elaĉetis nin el la malbeno de la leĝo, fariĝinte malbeno pro ni; ĉar estas skribite: Malbenita estas ĉiu, kiu pendas sur lignaĵo;"],[3,14,"por ke venu sur la nacianojn la beno de Abraham en Kristo Jesuo; por ke per fido ni ricevu la promeson de la Spirito.","por ke venu sur la nacianojn la beno de Abraham en Kristo Jesuo; por ke per fido ni ricevu la promeson de la Spirito."],[3,15,"Fratoj, mi parolas laŭ homo: Konfirmitan interligon, eĉ nur homan, neniu nuligas nek prialdonas.","Fratoj, mi parolas laŭ homo: Konfirmitan interligon, eĉ nur homan, neniu nuligas nek prialdonas."],[3,16,"Sed al Abraham kaj al lia semo la promesoj estis parolitaj. Li ne diras: Kaj al semoj, kvazaŭ pri multaj; sed kvazaŭ unu: Kaj al via semo, kiu estas Kristo.","Sed al Abraham kaj al lia semo la promesoj estis parolitaj. Li ne diras: Kaj al semoj, kvazaŭ pri multaj; sed kvazaŭ unu: Kaj al via semo, kiu estas Kristo."],[3,17,"Sed jen kion mi diras: Interligon, antaŭe konfirmitan de Dio, la leĝo, kiu venis kvarcent tridek jarojn poste, ne nuligas, tiel ke ĝi malefektivigus la promeson.","Sed jen kion mi diras: Interligon, antaŭe konfirmitan de Dio, la leĝo, kiu venis kvarcent tridek jarojn poste, ne nuligas, tiel ke ĝi malefektivigus la promeson."],[3,18,"Ĉar se la heredaĵo estas de la leĝo, ĝi jam ne estas de promeso; sed Dio ĝin donis al Abraham per promeso.","Ĉar se la heredaĵo estas de la leĝo, ĝi jam ne estas de promeso; sed Dio ĝin donis al Abraham per promeso."],[3,19,"Kio do estas la leĝo? Ĝi estis aldonita kaŭze de eraroj, ĝis venos la idaro, al kiu la promeso estas donita; ordigite per anĝeloj en la mano de interulo.","Kio do estas la leĝo? Ĝi estis aldonita kaŭze de eraroj, ĝis venos la idaro, al kiu la promeso estas donita; ordigite per anĝeloj en la mano de interulo."],[3,20,"Interulo ne estas de unu, sed Dio estas unu.","Interulo ne estas de unu, sed Dio estas unu."],[3,21,"Ĉu do la leĝo kontraŭstaras al la promesoj de Dio? Nepre ne! ĉar se estus donita leĝo, kiu povus vivigi, efektive justeco estus per la leĝo.","Ĉu do la leĝo kontraŭstaras al la promesoj de Dio? Nepre ne! ĉar se estus donita leĝo, kiu povus vivigi, efektive justeco estus per la leĝo."],[3,22,"Tamen la Skribo kune enŝlosis ĉion sub peko, por ke la promeso per fido al Kristo Jesuo estu donata al ĉiuj, kiuj fidas.","Tamen la Skribo kune enŝlosis ĉion sub peko, por ke la promeso per fido al Kristo Jesuo estu donata al ĉiuj, kiuj fidas."],[3,23,"Sed antaŭ ol fido venis, ni estis gardataj sub la leĝo, enŝlositaj por la fido malkaŝota.","Sed antaŭ ol fido venis, ni estis gardataj sub la leĝo, enŝlositaj por la fido malkaŝota."],[3,24,"Tial la leĝo fariĝis nia pedagogo, kondukanta al Kristo, por ke ni praviĝu per fido.","Tial la leĝo fariĝis nia pedagogo, kondukanta al Kristo, por ke ni praviĝu per fido."],[3,25,"Sed nun, post kiam la fido alvenis, ni jam ne estas sub pedagogo.","Sed nun, post kiam la fido alvenis, ni jam ne estas sub pedagogo."],[3,26,"Ĉar vi ĉiuj per la fido estas filoj de Dio en Kristo Jesuo.","Ĉar vi ĉiuj per la fido estas filoj de Dio en Kristo Jesuo."],[3,27,"Ĉar ĉiuj el vi, kiuj al Kristo baptiĝis, surmetis al si Kriston.","Ĉar ĉiuj el vi, kiuj al Kristo baptiĝis, surmetis al si Kriston."],[3,28,"Ne estas ja Judo nek Greko, ne estas sklavo nek liberulo, ne estas ja vira kaj virina; ĉar vi ĉiuj estas unu en Kristo Jesuo.","Ne estas ja Judo nek Greko, ne estas sklavo nek liberulo, ne estas ja vira kaj virina; ĉar vi ĉiuj estas unu en Kristo Jesuo."],[3,29,"Se do vi apartenas al Kristo, vere vi estas la idaro de Abraham, kaj heredantoj laŭ la promeso.","Se do vi apartenas al Kristo, vere vi estas la idaro de Abraham, kaj heredantoj laŭ la promeso."],[4,1,"Kaj mi sciigas vin, ke tiel longe, kiel la heredanto estas infano, li neniel malsimilas sklavon, kvankam li estas estro de ĉio;","Kaj mi sciigas vin, ke tiel longe, kiel la heredanto estas infano, li neniel malsimilas sklavon, kvankam li estas estro de ĉio;"],[4,2,"sed li estas sub guvernantoj kaj administrantoj, ĝis la templimo difinita de la patro.","sed li estas sub guvernantoj kaj administrantoj, ĝis la templimo difinita de la patro."],[4,3,"Tiel ankaŭ ni, dum ni estis infanoj, estis en sklaveco sub la elementoj de la mondo;","Tiel ankaŭ ni, dum ni estis infanoj, estis en sklaveco sub la elementoj de la mondo;"],[4,4,"sed kiam venis la pleneco de la tempo, Dio elsendis Sian Filon, el virino naskitan, sub leĝo naskitan,","sed kiam venis la pleneco de la tempo, Dio elsendis Sian Filon, el virino naskitan, sub leĝo naskitan,"],[4,5,"por reaĉeti tiujn, kiuj estas sub la leĝo, por ke ni ricevu la filadopton.","por reaĉeti tiujn, kiuj estas sub la leĝo, por ke ni ricevu la filadopton."],[4,6,"Kaj ĉar vi estas filoj, Dio elsendis la Spiriton de Sia Filo en niajn korojn, kriantan, Aba, Patro!","Kaj ĉar vi estas filoj, Dio elsendis la Spiriton de Sia Filo en niajn korojn, kriantan, Aba, Patro!"],[4,7,"Tiel ke ĉiu el vi estas jam ne sklavo, sed filo; kaj se filo, ankaŭ heredanto per Dio.","Tiel ke ĉiu el vi estas jam ne sklavo, sed filo; kaj se filo, ankaŭ heredanto per Dio."],[4,8,"Tamen, tiam ne konante Dion, vi estis en sklaveco al tiuj, kiuj nature ne estas dioj;","Tamen, tiam ne konante Dion, vi estis en sklaveco al tiuj, kiuj nature ne estas dioj;"],[4,9,"sed jam nun konante Dion, aŭ pli ĝuste, de Dio konate, kial vi returniĝas al la malfortaj kaj mizeraj elementoj, al kiuj vi deziras denove sklaviĝi?","sed jam nun konante Dion, aŭ pli ĝuste, de Dio konate, kial vi returniĝas al la malfortaj kaj mizeraj elementoj, al kiuj vi deziras denove sklaviĝi?"],[4,10,"Vi observas tagojn kaj monatojn kaj tempojn kaj jarojn.","Vi observas tagojn kaj monatojn kaj tempojn kaj jarojn."],[4,11,"Mi timas pri vi, ke eble mi vane laboris ĉe vi.","Mi timas pri vi, ke eble mi vane laboris ĉe vi."],[4,12,"Mi petegas vin, fratoj, estu kiel mi, ĉar mi ankaŭ estas kiel vi. Vi neniel al mi malbonfaris;","Mi petegas vin, fratoj, estu kiel mi, ĉar mi ankaŭ estas kiel vi. Vi neniel al mi malbonfaris;"],[4,13,"sed vi scias, ke pro malforteco de la karno mi la unuan fojon predikis al vi la evangelion;","sed vi scias, ke pro malforteco de la karno mi la unuan fojon predikis al vi la evangelion;"],[4,14,"kaj vian elprovon en mia karno vi ne malestimis nek abomenis, sed kvazaŭ anĝelon de Dio vi akceptis min, kvazaŭ Kriston Jesuon.","kaj vian elprovon en mia karno vi ne malestimis nek abomenis, sed kvazaŭ anĝelon de Dio vi akceptis min, kvazaŭ Kriston Jesuon."],[4,15,"Kie do estas via singratulado? mi atestas al vi, ke se estus eble, vi estus elŝirintaj viajn okulojn kaj donintaj ilin al mi.","Kie do estas via singratulado? mi atestas al vi, ke se estus eble, vi estus elŝirintaj viajn okulojn kaj donintaj ilin al mi."],[4,16,"Ĉu mi do per verdirado fariĝis al vi malamiko?","Ĉu mi do per verdirado fariĝis al vi malamiko?"],[4,17,"Ili fervore serĉas vin, ne bone; ili eĉ volas elŝlosi vin, por ke vi serĉu ilin.","Ili fervore serĉas vin, ne bone; ili eĉ volas elŝlosi vin, por ke vi serĉu ilin."],[4,18,"Sed estas bone esti fervore serĉata ĉiam en bona afero, kaj ne nur tiam, kiam mi estas ĉe vi.","Sed estas bone esti fervore serĉata ĉiam en bona afero, kaj ne nur tiam, kiam mi estas ĉe vi."],[4,19,"Miaj infanetoj, pro kiuj mi denove suferas naskodoloron, ĝis Kristo formiĝos en vi,","Miaj infanetoj, pro kiuj mi denove suferas naskodoloron, ĝis Kristo formiĝos en vi,"],[4,20,"mi tute deziris esti ĉe vi nun, kaj ŝanĝi mian voĉon; ĉar vere mi dubas pri vi.","mi tute deziris esti ĉe vi nun, kaj ŝanĝi mian voĉon; ĉar vere mi dubas pri vi."],[4,21,"Diru al mi, vi, kiuj volas esti sub la leĝo, ĉu vi ne aŭskultas la leĝon?","Diru al mi, vi, kiuj volas esti sub la leĝo, ĉu vi ne aŭskultas la leĝon?"],[4,22,"Ĉar estas skribite, ke Abraham havis du filojn, unu el la sklavino kaj unu el la liberulino.","Ĉar estas skribite, ke Abraham havis du filojn, unu el la sklavino kaj unu el la liberulino."],[4,23,"Tamen tiu el la sklavino naskiĝis laŭ la karno, sed ĉi tiu el la liberulino naskiĝis per promeso.","Tamen tiu el la sklavino naskiĝis laŭ la karno, sed ĉi tiu el la liberulino naskiĝis per promeso."],[4,24,"Ĉi tio enhavas alegorion; ĉar la du virinoj estas du interligoj, unu el la monto Sinaj, por sklaveco naskante, kiu estas Hagar.","Ĉi tio enhavas alegorion; ĉar la du virinoj estas du interligoj, unu el la monto Sinaj, por sklaveco naskante, kiu estas Hagar."],[4,25,"Ĉar tiu Hagar estas la monto Sinaj en Arabujo, kaj prezentas la nunan Jerusalemon, ĉar ŝi estas sklavigita kune kun siaj infanoj.","Ĉar tiu Hagar estas la monto Sinaj en Arabujo, kaj prezentas la nunan Jerusalemon, ĉar ŝi estas sklavigita kune kun siaj infanoj."],[4,26,"Sed la supera Jerusalem estas libera, kiu estas patrino nia.","Sed la supera Jerusalem estas libera, kiu estas patrino nia."],[4,27,"Estas ja skribite: Ĝoju, ho senfruktulino, kiu ne naskis, Sonigu kanton kaj ĝojkriu, ho vi, kiu ne suferas naskodoloron; Ĉar la forlasitino havos pli da infanoj, ol la havanta edzon.","Estas ja skribite: Ĝoju, ho senfruktulino, kiu ne naskis, Sonigu kanton kaj ĝojkriu, ho vi, kiu ne suferas naskodoloron; Ĉar la forlasitino havos pli da infanoj, ol la havanta edzon."],[4,28,"Sed ni, fratoj, estas filoj de promeso tiel same, kiel Isaak.","Sed ni, fratoj, estas filoj de promeso tiel same, kiel Isaak."],[4,29,"Sed kiel tiam la laŭ karno naskita persekutis la laŭspiritulon, tiel estas ankaŭ nuntempe.","Sed kiel tiam la laŭ karno naskita persekutis la laŭspiritulon, tiel estas ankaŭ nuntempe."],[4,30,"Sed kion diras la Skribo? Forpelu la sklavinon kaj ŝian filon; ĉar la filo de la sklavino ne heredos kun la filo de la liberulino.","Sed kion diras la Skribo? Forpelu la sklavinon kaj ŝian filon; ĉar la filo de la sklavino ne heredos kun la filo de la liberulino."],[4,31,"Tial, fratoj, ni estas filoj ne de sklavino, sed de la liberulino.","Tial, fratoj, ni estas filoj ne de sklavino, sed de la liberulino."],[5,1,"Por libereco Kristo nin liberigis; tial staru fortike, kaj ne reimplikiĝu en jugon de sklaveco.","Por libereco Kristo nin liberigis; tial staru fortike, kaj ne reimplikiĝu en jugon de sklaveco."],[5,2,"Jen mi, Paŭlo, diras al vi, ke, se vi cirkumcidiĝos, Kristo al vi tute ne utilos.","Jen mi, Paŭlo, diras al vi, ke, se vi cirkumcidiĝos, Kristo al vi tute ne utilos."],[5,3,"Mi denove atestas al ĉiu homo cirkumcidata, ke li estas ŝuldanto, por plenumi la tutan leĝon.","Mi denove atestas al ĉiu homo cirkumcidata, ke li estas ŝuldanto, por plenumi la tutan leĝon."],[5,4,"Vi, kiuj volas vin pravigi per la leĝo, apartiĝis for de Kristo; vi forfalis de graco.","Vi, kiuj volas vin pravigi per la leĝo, apartiĝis for de Kristo; vi forfalis de graco."],[5,5,"Ĉar ni en la Spirito atendas la esperon de justeco per la fido.","Ĉar ni en la Spirito atendas la esperon de justeco per la fido."],[5,6,"Ĉar en Kristo Jesuo nek cirkumcido nek necirkumcido valoras ion, sed nur fido, energianta per amo.","Ĉar en Kristo Jesuo nek cirkumcido nek necirkumcido valoras ion, sed nur fido, energianta per amo."],[5,7,"Vi bone kuradis; kiu vin malhelpis, ke vi ne obeu la veron?","Vi bone kuradis; kiu vin malhelpis, ke vi ne obeu la veron?"],[5,8,"Ĉi tiu influo ne venas de tiu, kiu vin vokas.","Ĉi tiu influo ne venas de tiu, kiu vin vokas."],[5,9,"Malmulto da fermentaĵo fermentigas la tutan mason.","Malmulto da fermentaĵo fermentigas la tutan mason."],[5,10,"Mi fidas pri vi en la Sinjoro, ke vi ne alie sentados; sed tiu, kiu malkvietigas vin, elportos sian propran juĝon, kiu ajn li estas.","Mi fidas pri vi en la Sinjoro, ke vi ne alie sentados; sed tiu, kiu malkvietigas vin, elportos sian propran juĝon, kiu ajn li estas."],[5,11,"Sed mi, fratoj, se mi ankoraŭ predikas cirkumcidon, kial mi estas ankoraŭ persekutata? tiuokaze la falpuŝilo de la kruco estas formovita.","Sed mi, fratoj, se mi ankoraŭ predikas cirkumcidon, kial mi estas ankoraŭ persekutata? tiuokaze la falpuŝilo de la kruco estas formovita."],[5,12,"Mi volus, ke tiuj, kiuj vin maltrankviligas, sin fortranĉu.","Mi volus, ke tiuj, kiuj vin maltrankviligas, sin fortranĉu."],[5,13,"Ĉar vi, fratoj, estas vokitaj al libereco; tamen ne uzu vian liberecon kiel pretekston por la karno, sed per amo servu unu la alian.","Ĉar vi, fratoj, estas vokitaj al libereco; tamen ne uzu vian liberecon kiel pretekston por la karno, sed per amo servu unu la alian."],[5,14,"Ĉar la tuta leĝo estas plenumata en unu diro, jene: Amu vian proksimulon kiel vin mem.","Ĉar la tuta leĝo estas plenumata en unu diro, jene: Amu vian proksimulon kiel vin mem."],[5,15,"Sed se vi mordas kaj manĝegas unu la alian, gardu vin, ke vi ne estu detruitaj unu de la alia.","Sed se vi mordas kaj manĝegas unu la alian, gardu vin, ke vi ne estu detruitaj unu de la alia."],[5,16,"Sed mi diras: Iradu laŭ la Spirito, kaj la deziregon de la karno vi ne plenumos.","Sed mi diras: Iradu laŭ la Spirito, kaj la deziregon de la karno vi ne plenumos."],[5,17,"Ĉar la karno deziregas kontraŭ la Spirito, kaj la Spirito kontraŭ la karno; ĉar ĉi ĉiuj interbatalas reciproke, por ke vi ne faru tion, kion vi volas.","Ĉar la karno deziregas kontraŭ la Spirito, kaj la Spirito kontraŭ la karno; ĉar ĉi ĉiuj interbatalas reciproke, por ke vi ne faru tion, kion vi volas."],[5,18,"Sed se vi estas kondukataj de la Sinjoro, vi jam ne estas sub la leĝo.","Sed se vi estas kondukataj de la Sinjoro, vi jam ne estas sub la leĝo."],[5,19,"Evidentaj estas la faroj de la karno, kiuj estas malĉasteco, malpureco, voluptemo,","Evidentaj estas la faroj de la karno, kiuj estas malĉasteco, malpureco, voluptemo,"],[5,20,"idolkulto, sorĉado, malamikeco, malpaco, ĵaluzoj, koleregoj, partiemeco, skismoj, herezoj,","idolkulto, sorĉado, malamikeco, malpaco, ĵaluzoj, koleregoj, partiemeco, skismoj, herezoj,"],[5,21,"envioj, ebrieco, diboĉado, kaj aliaj similaj; pri kiuj mi avertas vin, kiel mi jam antaŭe admonis vin, ke tiuj, kiuj tion faradas, ne heredos la regnon de Dio.","envioj, ebrieco, diboĉado, kaj aliaj similaj; pri kiuj mi avertas vin, kiel mi jam antaŭe admonis vin, ke tiuj, kiuj tion faradas, ne heredos la regnon de Dio."],[5,22,"Sed la frukto de la Spirito estas amo, ĝojo, paco, pacienco, komplezo, bonkoreco, fideleco,","Sed la frukto de la Spirito estas amo, ĝojo, paco, pacienco, komplezo, bonkoreco, fideleco,"],[5,23,"mildeco, sinregado; kontraŭ tiaj ne ekzistas leĝo.","mildeco, sinregado; kontraŭ tiaj ne ekzistas leĝo."],[5,24,"Kaj tiuj, kiuj apartenas al Kristo Jesuo, jam krucumis la karnon kun ĝiaj pasioj kaj voluptoj.","Kaj tiuj, kiuj apartenas al Kristo Jesuo, jam krucumis la karnon kun ĝiaj pasioj kaj voluptoj."],[5,25,"Se ni vivas per la Spirito, en la Spirito ni ankaŭ iradu.","Se ni vivas per la Spirito, en la Spirito ni ankaŭ iradu."],[5,26,"Ni ne fariĝu fanfaronemaj, incitante kaj enviante unu la alian.","Ni ne fariĝu fanfaronemaj, incitante kaj enviante unu la alian."],[6,1,"Fratoj, eĉ se homo estos trovita en ia kulpo, vi, kiuj estas spiritaj, restarigu tiun per spirito de mildeco; rigardante vin, ĉiu sin mem, por ke vi ne estu tentataj.","Fratoj, eĉ se homo estos trovita en ia kulpo, vi, kiuj estas spiritaj, restarigu tiun per spirito de mildeco; rigardante vin, ĉiu sin mem, por ke vi ne estu tentataj."],[6,2,"Reciproke subtenadu viajn ŝarĝojn, kaj tiamaniere plenumu la leĝon de Kristo.","Reciproke subtenadu viajn ŝarĝojn, kaj tiamaniere plenumu la leĝon de Kristo."],[6,3,"Ĉar, se iu, estante nenio, sin estimas, kvazaŭ li estas io, li sin trompas.","Ĉar, se iu, estante nenio, sin estimas, kvazaŭ li estas io, li sin trompas."],[6,4,"Sed ĉiu kontrolu sian propran faradon, kaj tiam li havos singratuladon pri si mem, kaj ne pri sia proksimulo.","Sed ĉiu kontrolu sian propran faradon, kaj tiam li havos singratuladon pri si mem, kaj ne pri sia proksimulo."],[6,5,"Ĉar ĉiu devas subteni sian propran portaĵon.","Ĉar ĉiu devas subteni sian propran portaĵon."],[6,6,"Tiu, kiu estas instruata en la parolo de Dio, partoprenu kun tiu, kiu lin instruas, en ĉiuj bonaĵoj.","Tiu, kiu estas instruata en la parolo de Dio, partoprenu kun tiu, kiu lin instruas, en ĉiuj bonaĵoj."],[6,7,"Ne trompiĝu; Dio ne estas mokata; ĉar ĉion, kion oni semas, tion ankaŭ li rikoltos.","Ne trompiĝu; Dio ne estas mokata; ĉar ĉion, kion oni semas, tion ankaŭ li rikoltos."],[6,8,"Ĉar kiu semas por sia karno, el la karno tiu rikoltos putradon; sed kiu semas por la Spirito, el la Spirito tiu rikoltos eternan vivon.","Ĉar kiu semas por sia karno, el la karno tiu rikoltos putradon; sed kiu semas por la Spirito, el la Spirito tiu rikoltos eternan vivon."],[6,9,"Kaj ni ne laciĝu en bonfarado; ĉar ĝustatempe ni rikoltos, se ni ne senfortiĝos.","Kaj ni ne laciĝu en bonfarado; ĉar ĝustatempe ni rikoltos, se ni ne senfortiĝos."],[6,10,"Tial laŭ nia oportuna tempo ni bonfaradu al ĉiuj, precipe al tiuj, kiuj apartenas al la familio de la fido.","Tial laŭ nia oportuna tempo ni bonfaradu al ĉiuj, precipe al tiuj, kiuj apartenas al la familio de la fido."],[6,11,"Vidu, per kiaj grandaj literoj mi skribis al vi propramane.","Vidu, per kiaj grandaj literoj mi skribis al vi propramane."],[6,12,"Kiuj deziras sin paradi per la karno, tiuj devigas vin cirkumcidiĝi; sole por ke ili ne estu persekutataj pro la kruco de Kristo.","Kiuj deziras sin paradi per la karno, tiuj devigas vin cirkumcidiĝi; sole por ke ili ne estu persekutataj pro la kruco de Kristo."],[6,13,"Ĉar eĉ tiuj mem, kiuj cirkumcidiĝas, ne observas la leĝon; sed ili deziras, ke vi cirkumcidiĝu, por ke ili fanfaronu pri via karno.","Ĉar eĉ tiuj mem, kiuj cirkumcidiĝas, ne observas la leĝon; sed ili deziras, ke vi cirkumcidiĝu, por ke ili fanfaronu pri via karno."],[6,14,"Sed por mi ne estu fanfarono krom pri la kruco de nia Sinjoro Jesuo Kristo, per kiu la mondo estas krucumita al mi, kaj mi al la mondo.","Sed por mi ne estu fanfarono krom pri la kruco de nia Sinjoro Jesuo Kristo, per kiu la mondo estas krucumita al mi, kaj mi al la mondo."],[6,15,"Ĉar nek cirkumcido nek necirkumcido estas io, sed nova kreitaĵo.","Ĉar nek cirkumcido nek necirkumcido estas io, sed nova kreitaĵo."],[6,16,"Kaj kiuj irados laŭ tiu regulo, paco kaj kompato estu sur ili ĉiuj, kaj sur la Izrael de Dio.","Kaj kiuj irados laŭ tiu regulo, paco kaj kompato estu sur ili ĉiuj, kaj sur la Izrael de Dio."],[6,17,"De nun neniu min ĝenu, ĉar mi portas en mia korpo la signojn de Jesuo.","De nun neniu min ĝenu, ĉar mi portas en mia korpo la signojn de Jesuo."],[6,18,"La graco de nia Sinjoro Jesuo Kristo estu kun via spirito, fratoj. Amen.","La graco de nia Sinjoro Jesuo Kristo estu kun via spirito, fratoj. Amen."]]}};